{
  "watches": [
    {
      "name": "edit-blur-safety",
      "description": "Edit interaction must not throw when blur and Enter fire in the same real-browser interaction",
      "targets": [
        "features/edit-todo.feature:Editing must not throw when blur and Enter fire in the same interaction"
      ]
    },
    {
      "name": "routing-hash-update",
      "description": "Filter links must update the URL hash so the back button works in a real browser",
      "targets": [
        "features/routing.feature:Filter link updates the URL hash",
        "features/routing.feature:Back button returns to previous filter view",
        "features/routing.feature:Filter handler must not prevent anchor default navigation"
      ]
    },
    {
      "name": "regression",
      "description": "Existing scenarios must remain green after the fixes",
      "targets": [
        "features/edit-todo.feature",
        "features/routing.feature"
      ]
    }
  ]
}

(function () {
	'use strict';

	var STORAGE_KEY = 'todos-vanillajs';

	// Model
	var todos = [];
	var currentFilter = 'all';

	// DOM elements
	var newTodoInput = document.querySelector('.new-todo');
	var todoList = document.querySelector('.todo-list');
	var mainSection = document.querySelector('.main');
	var footer = document.querySelector('.footer');
	var toggleAllCheckbox = document.getElementById('toggle-all');
	var clearCompletedButton = document.querySelector('.clear-completed');
	var filterLinks = document.querySelectorAll('.filters a');

	// Load todos from localStorage
	function loadTodos() {
		var stored = localStorage.getItem(STORAGE_KEY);
		if (stored) {
			try {
				todos = JSON.parse(stored);
			} catch (e) {
				todos = [];
			}
		}
	}

	// Save todos to localStorage
	function saveTodos() {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	// Generate unique ID
	function generateId() {
		return Date.now().toString(36) + Math.random().toString(36).substr(2);
	}

	// Create a new todo
	function addTodo(title) {
		title = title.trim();
		if (title === '') {
			return;
		}
		var todo = {
			id: generateId(),
			title: title,
			completed: false
		};
		todos.push(todo);
		saveTodos();
		render();
	}

	// Toggle todo completion
	function toggleTodo(id) {
		for (var i = 0; i < todos.length; i++) {
			if (todos[i].id === id) {
				todos[i].completed = !todos[i].completed;
				break;
			}
		}
		saveTodos();
		render();
	}

	// Delete a todo
	function deleteTodo(id) {
		todos = todos.filter(function (todo) {
			return todo.id !== id;
		});
		saveTodos();
		render();
	}

	// Edit a todo
	function editTodo(id, newTitle) {
		newTitle = newTitle.trim();
		if (newTitle === '') {
			deleteTodo(id);
			return;
		}
		for (var i = 0; i < todos.length; i++) {
			if (todos[i].id === id) {
				todos[i].title = newTitle;
				break;
			}
		}
		saveTodos();
		render();
	}

	// Clear completed todos
	function clearCompleted() {
		todos = todos.filter(function (todo) {
			return !todo.completed;
		});
		saveTodos();
		render();
	}

	// Toggle all todos
	function toggleAll() {
		var allCompleted = todos.every(function (todo) {
			return todo.completed;
		});
		var newState = !allCompleted;
		todos.forEach(function (todo) {
			todo.completed = newState;
		});
		saveTodos();
		render();
	}

	// Filter todos based on current filter
	function getFilteredTodos() {
		switch (currentFilter) {
			case 'active':
				return todos.filter(function (todo) {
					return !todo.completed;
				});
			case 'completed':
				return todos.filter(function (todo) {
					return todo.completed;
				});
			default:
				return todos;
		}
	}

	// Create a new <li> element for a todo
	function createTodoElement(todo) {
		var li = document.createElement('li');
		li.dataset.id = todo.id;
		if (todo.completed) {
			li.classList.add('completed');
		}

		var viewDiv = document.createElement('div');
		viewDiv.className = 'view';

		var toggleInput = document.createElement('input');
		toggleInput.className = 'toggle';
		toggleInput.type = 'checkbox';
		if (todo.completed) {
			toggleInput.checked = true;
		}

		var label = document.createElement('label');
		label.textContent = todo.title;

		var destroyButton = document.createElement('button');
		destroyButton.className = 'destroy';

		viewDiv.appendChild(toggleInput);
		viewDiv.appendChild(label);
		viewDiv.appendChild(destroyButton);

		var editInput = document.createElement('input');
		editInput.className = 'edit';
		editInput.value = todo.title;

		li.appendChild(viewDiv);
		li.appendChild(editInput);

		return li;
	}

	// Update an existing <li> element in place
	function updateTodoElement(li, todo) {
		// Update completed state
		if (todo.completed) {
			li.classList.add('completed');
		} else {
			li.classList.remove('completed');
		}

		// Update toggle checkbox
		var toggleInput = li.querySelector('.toggle');
		toggleInput.checked = todo.completed;

		// Update label text
		var label = li.querySelector('label');
		label.textContent = todo.title;

		// Update edit input value
		var editInput = li.querySelector('.edit');
		editInput.value = todo.title;
	}

	// Render the app
	function render() {
		var filteredTodos = getFilteredTodos();
		var activeTodos = todos.filter(function (todo) {
			return !todo.completed;
		});
		var completedTodos = todos.filter(function (todo) {
			return todo.completed;
		});

		// Build a map of existing <li> elements by data-id
		var existingLis = todoList.querySelectorAll('li');
		var existingMap = {};
		for (var i = 0; i < existingLis.length; i++) {
			existingMap[existingLis[i].dataset.id] = existingLis[i];
		}

		// Build a set of filtered todo IDs
		var filteredIds = {};
		filteredTodos.forEach(function (todo) {
			filteredIds[todo.id] = true;
		});

		// Remove <li> elements for todos not in the filtered set
		var currentLis = todoList.querySelectorAll('li');
		for (var j = currentLis.length - 1; j >= 0; j--) {
			var existingLi = currentLis[j];
			if (!filteredIds[existingLi.dataset.id]) {
				todoList.removeChild(existingLi);
			}
		}

		// Add or update <li> elements in order
		filteredTodos.forEach(function (todo) {
			var li = existingMap[todo.id];
			if (li) {
				// Update existing element in place
				updateTodoElement(li, todo);
			} else {
				// Create new element and append
				li = createTodoElement(todo);
				todoList.appendChild(li);
			}
		});

		// Update main section visibility
		if (todos.length > 0) {
			mainSection.style.display = 'block';
			footer.style.display = 'block';
		} else {
			mainSection.style.display = 'none';
			footer.style.display = 'none';
		}

		// Update toggle all checkbox
		toggleAllCheckbox.checked = todos.length > 0 && activeTodos.length === 0;

		// Update count
		var count = activeTodos.length;
		var countText = count === 1 ? ' item left' : ' items left';
		var todoCountSpan = document.querySelector('.todo-count');
		todoCountSpan.innerHTML = '';
		var strong = document.createElement('strong');
		strong.textContent = String(count);
		todoCountSpan.appendChild(strong);
		todoCountSpan.appendChild(document.createTextNode(countText));

		// Update clear completed button
		if (completedTodos.length > 0) {
			clearCompletedButton.style.display = 'block';
		} else {
			clearCompletedButton.style.display = 'none';
		}

		// Update filter links
		filterLinks.forEach(function (link) {
			if (link.getAttribute('href') === '#/' + currentFilter ||
				(currentFilter === 'all' && link.getAttribute('href') === '#/')) {
				link.classList.add('selected');
			} else {
				link.classList.remove('selected');
			}
		});
	}

	// Escape HTML to prevent XSS
	function escapeHtml(text) {
		var div = document.createElement('div');
		div.appendChild(document.createTextNode(text));
		return div.innerHTML;
	}

	// Event delegation for todo list
	function handleTodoListClick(e) {
		var target = e.target;
		var li = target.closest('li');
		if (!li) return;
		var id = li.dataset.id;

		if (target.classList.contains('toggle')) {
			toggleTodo(id);
		} else if (target.classList.contains('destroy')) {
			deleteTodo(id);
		}
	}

	function handleTodoListDblClick(e) {
		var target = e.target;
		if (target.tagName.toLowerCase() !== 'label') return;
		var li = target.closest('li');
		if (!li) return;
		li.classList.add('editing');
		var editInput = li.querySelector('.edit');
		editInput.focus();
	}

	function handleTodoListKeyDown(e) {
		if (e.key === 'Enter') {
			var target = e.target;
			if (target.classList.contains('edit')) {
				var li = target.closest('li');
				var id = li.dataset.id;
				editTodo(id, target.value);
				li.classList.remove('editing');
			}
		} else if (e.key === 'Escape') {
			var target = e.target;
			if (target.classList.contains('edit')) {
				var li = target.closest('li');
				li.classList.remove('editing');
				target.value = li.querySelector('label').textContent;
			}
		}
	}

	function handleTodoListBlur(e) {
		var target = e.target;
		if (target.classList.contains('edit')) {
			var li = target.closest('li');
			var id = li.dataset.id;
			editTodo(id, target.value);
			li.classList.remove('editing');
		}
	}

	// New todo input
	function handleNewTodoKeyDown(e) {
		if (e.key === 'Enter') {
			addTodo(newTodoInput.value);
			newTodoInput.value = '';
		}
	}

	// Toggle all
	function handleToggleAllChange() {
		toggleAll();
	}

	// Clear completed
	function handleClearCompletedClick() {
		clearCompleted();
	}

	// Filter links
	function handleFilterClick(e) {
		e.preventDefault();
		var href = e.target.getAttribute('href');
		if (href === '#/') {
			currentFilter = 'all';
		} else if (href === '#/active') {
			currentFilter = 'active';
		} else if (href === '#/completed') {
			currentFilter = 'completed';
		}
		render();
	}

	// Handle routing
	function handleHashChange() {
		var hash = window.location.hash;
		if (hash === '#/active') {
			currentFilter = 'active';
		} else if (hash === '#/completed') {
			currentFilter = 'completed';
		} else {
			currentFilter = 'all';
		}
		render();
	}

	// Initialize
	function init() {
		loadTodos();
		render();

		// Event listeners
		newTodoInput.addEventListener('keydown', handleNewTodoKeyDown);
		todoList.addEventListener('click', handleTodoListClick);
		todoList.addEventListener('dblclick', handleTodoListDblClick);
		todoList.addEventListener('keydown', handleTodoListKeyDown);
		todoList.addEventListener('blur', handleTodoListBlur, true);
		toggleAllCheckbox.addEventListener('change', handleToggleAllChange);
		clearCompletedButton.addEventListener('click', handleClearCompletedClick);
		filterLinks.forEach(function (link) {
			link.addEventListener('click', handleFilterClick);
		});
		window.addEventListener('hashchange', handleHashChange);

		// Handle initial hash
		handleHashChange();
	}

	init();
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// Background
Given('the app is loaded', function () {
  // App is already loaded by world.js Before hook
  assert.ok(this.document, 'App should be loaded');
});

// Adding todos
When('I type {string} in the new todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
});

When('I press Enter', function () {
  // Check if we're in edit mode
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (editInput) {
    editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  } else {
    const input = this.document.querySelector('.new-todo');
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  }
});

Then('I should see {string} in the todo list', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === text);
  assert.ok(found, `Expected to see "${text}" in todo list`);
});

Then('the new todo input should be empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'New todo input should be empty');
});

Then('I should see no todos', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected no todos');
});

// Toggle todos
Given('I have a todo {string}', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

Given('I have a completed todo {string}', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  // Find and toggle the todo
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  const li = label.closest('li');
  const toggle = li.querySelector('.toggle');
  toggle.click();
});

When('I toggle the todo {string}', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  const li = label.closest('li');
  const toggle = li.querySelector('.toggle');
  toggle.click();
});

Then('the todo {string} should be completed', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  const li = label.closest('li');
  assert.ok(li.classList.contains('completed'), `Expected "${text}" to be completed`);
});

Then('the todo {string} should be active', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  const li = label.closest('li');
  assert.ok(!li.classList.contains('completed'), `Expected "${text}" to be active`);
});

// Delete todos
When('I delete the todo {string}', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  const li = label.closest('li');
  const destroy = li.querySelector('.destroy');
  destroy.click();
});

// Edit todos
When('I double-click the todo {string}', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('I type {string} in the edit input', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'Expected edit input to be visible');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Escape', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'Expected edit input to be visible');
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
});

Then('I should not see {string} in the todo list', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === text);
  assert.ok(!found, `Expected not to see "${text}" in todo list`);
});

// Toggle all
Given('I have todos {string} and {string}', function (text1, text2) {
  const input = this.document.querySelector('.new-todo');
  input.value = text1;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  input.value = text2;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

Given('I have completed todos {string} and {string}', function (text1, text2) {
  const input = this.document.querySelector('.new-todo');
  input.value = text1;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  input.value = text2;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  // Toggle all to complete
  const toggleAll = this.document.getElementById('toggle-all');
  toggleAll.click();
});

When('I toggle all todos', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  toggleAll.click();
});

Then('all todos should be completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  items.forEach(li => {
    assert.ok(li.classList.contains('completed'), 'Expected todo to be completed');
  });
});

Then('all todos should be active', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  items.forEach(li => {
    assert.ok(!li.classList.contains('completed'), 'Expected todo to be active');
  });
});

// Clear completed
When('I click clear completed', function () {
  const clearButton = this.document.querySelector('.clear-completed');
  clearButton.click();
});

// Counter
Then('the counter should show {string}', function (text) {
  const todoCount = this.document.querySelector('.todo-count');
  assert.ok(todoCount.textContent.includes(text), `Expected counter to show "${text}"`);
});

// Filtering
When('I click the {string} filter', function (filterName) {
  const links = this.document.querySelectorAll('.filters a');
  const link = Array.from(links).find(a => a.textContent === filterName);
  assert.ok(link, `Expected to find "${filterName}" filter`);
  link.click();
});

// Visibility
Then('the main section should be hidden', function () {
  const main = this.document.querySelector('.main');
  assert.strictEqual(main.style.display, 'none', 'Expected main section to be hidden');
});

Then('the main section should be visible', function () {
  const main = this.document.querySelector('.main');
  assert.notStrictEqual(main.style.display, 'none', 'Expected main section to be visible');
});

Then('the footer should be hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.strictEqual(footer.style.display, 'none', 'Expected footer to be hidden');
});

Then('the footer should be visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.notStrictEqual(footer.style.display, 'none', 'Expected footer to be visible');
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
